const nights = [
 {title:'Mirror Magic',day:'Sunday',description:'Bring out the shine, bring out the tradition. A night for mirror-work details and beautifully coordinated pairs.',theme:'Best Dressed Pair · Traditional attire with mirror highlighting.'},
 {title:'Ras Leela',day:'Monday',description:'Let the festive magic unfold. Step into an evening of colour, movement and the joy of celebrating together.',theme:'Celebrate the spirit of Ras Leela in your festive best.'},
 {title:'The art of the detail',day:'Tuesday',description:'Let your accessories tell a story. Bring a little imagination and a whole lot of traditional charm.',theme:'Men: Best Brooch · Women: Best Decorated Hand Fan.'},
 {title:'Behind the sparkle',day:'Wednesday',description:'Creativity meets glamour. Make a statement with an eye mask that is as unforgettable as the evening.',theme:'Best Eye Mask · Bring your most creative festive design.'},
 {title:'Made to stand out',day:'Thursday',description:'Every little detail is a chance to create something extraordinary. Give everyday objects a festive new life.',theme:'Men: Best Decorated Gloves & Tall Stick · Women: Best Decorated Kitchen Prop.'},
 {title:'Better together',day:'Friday',description:'Gather your people and find your rhythm. Bring your props, your creativity and your shared love of dance.',theme:'Group Dance with Prop · Minimum 9 and maximum 12 members.'},
 {title:'Little stars. Big dreams.',day:'Saturday',description:'What would Navratri look like a hundred years from now? Let little imaginations travel to the year 2126.',theme:'Best 2126 Look · For children aged 0–5 years.'},
 {title:'Tradition, reimagined',day:'Sunday',description:'A fresh expression of a timeless celebration. Bring your own personality to a beautifully traditional look.',theme:'Men: Best Creative Sleeveless Vest · Women: Best Traditional Unique Bottoms (skirt, bellbottoms, etc.).'},
 {title:'The Grand Finale',day:'Monday',description:'One last evening. A thousand memories to take home. Let’s celebrate an unforgettable Navratri together.',theme:'19 October · The final night of Legend Navratri Utsav 2026.'}
];
const tabs = document.querySelector('.day-tabs');
nights.forEach((night,index)=>{const tab=document.createElement('button');tab.id=`day-${index}`;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','night-panel');tab.innerHTML=`<span>NIGHT ${String(index+1).padStart(2,'0')}</span><strong>${11+index}</strong><span>OCT · ${night.day.slice(0,3).toUpperCase()}</span>`;tab.addEventListener('click',()=>selectNight(index));tab.addEventListener('keydown',event=>{let target;if(event.key==='ArrowRight')target=(index+1)%9;if(event.key==='ArrowLeft')target=(index+8)%9;if(event.key==='Home')target=0;if(event.key==='End')target=8;if(target!==undefined){event.preventDefault();selectNight(target);tabs.children[target].focus();}});tabs.append(tab);});
let selected=0;
function selectNight(index){selected=index;const night=nights[index];[...tabs.children].forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;});document.querySelector('#night-panel').setAttribute('aria-labelledby',`day-${index}`);document.querySelector('#night-date').textContent=`NIGHT ${String(index+1).padStart(2,'0')} · ${night.day.toUpperCase()}, ${11+index} OCTOBER`;document.querySelector('#night-title').textContent=night.title;document.querySelector('#night-description').textContent=night.description;document.querySelector('#night-theme').textContent=night.theme;document.querySelector('#night-count').textContent=`${String(index+1).padStart(2,'0')} / 09 NIGHTS`;document.querySelector('#night-image').src=`assets/poster-${index+2}.png`;document.querySelector('#night-image').alt=`${night.title} — official poster for ${11+index} October 2026`;}
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const eventDate=/^2026-10-(\d\d)$/.exec(today);selectNight(eventDate&&+eventDate[1]>=11&&+eventDate[1]<=19?+eventDate[1]-11:0);
document.querySelector('#previous-night').addEventListener('click',()=>selectNight((selected+8)%9));document.querySelector('#next-night').addEventListener('click',()=>selectNight((selected+1)%9));
const dialog=document.querySelector('#poster-dialog');function openPoster(index){document.querySelector('#modal-image').src=`assets/poster-${index}.png`;dialog.showModal();document.body.style.overflow='hidden';}function closePoster(){dialog.close();}dialog.addEventListener('close',()=>document.body.style.overflow='');document.querySelector('.close-dialog').addEventListener('click',closePoster);dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closePoster();}});document.querySelector('#view-poster').addEventListener('click',()=>openPoster(selected+2));document.querySelector('.night-image-button').addEventListener('click',()=>openPoster(selected+2));document.querySelectorAll('[data-poster]').forEach(button=>button.addEventListener('click',()=>openPoster(Number(button.dataset.poster))));
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰';}));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰';menu.focus();}});
